//! Generated files are checked in; normal tests detect drift without modifying sources.
use ts_rs::TS;

#[test]
fn typescript_contracts_match_rust() {
    let cfg = ts_rs::Config::new().with_large_int("number");
    let mut output =
        String::from("// Generated by npm run contracts:generate. Edit the Rust types instead.\n");
    output.push_str("export type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };\n");
    macro_rules! emit {
        ($ty:ty) => {
            output.push_str("export ");
            output.push_str(&<$ty>::decl(&cfg));
            output.push('\n');
        };
    }
    emit!(crate::error::ErrorKind);
    emit!(crate::error::ErrorPayload);
    emit!(crate::models::Engine);
    emit!(crate::models::ColumnMeta);
    emit!(crate::models::ConnectionPublic);
    emit!(crate::models::SaveConnectionRequest);
    emit!(crate::models::SaveConnectionResult);
    emit!(crate::models::TestResult);
    emit!(crate::models::ConnectResult);
    emit!(crate::models::ExecuteSqlRequest);
    emit!(crate::models::StatementResult);
    emit!(crate::models::ExecuteSqlResponse);
    emit!(crate::models::FilterSpec);
    emit!(crate::models::SortSpec);
    emit!(crate::models::FetchRowsRequest);
    emit!(crate::models::DataPage);
    emit!(crate::models::FieldValue);
    emit!(crate::models::RowChange);
    emit!(crate::models::CommitRequest);
    emit!(crate::models::CommitResult);
    emit!(crate::models::ExportTableRequest);
    emit!(crate::models::ExportSqlRequest);
    emit!(crate::models::ImportCsvRequest);
    emit!(crate::models::ExportResult);
    emit!(crate::models::ImportResult);
    emit!(crate::models::AppInfo);
    emit!(crate::studio::types::SqlText);
    emit!(crate::studio::types::ParamBind);
    emit!(crate::studio::types::BindRequest);
    emit!(crate::studio::types::Snippet);
    emit!(crate::studio::types::GridResult);
    emit!(crate::studio::types::ErTable);
    emit!(crate::studio::types::ErEdge);
    emit!(crate::studio::types::ErGraph);
    emit!(crate::studio::types::ObjectRef);
    emit!(crate::studio::types::FileExportRequest);
    emit!(crate::studio::types::FileExportResult);
    emit!(crate::studio::types::FileImportRequest);
    emit!(crate::studio::types::PairRequest);
    emit!(crate::studio::types::DiffResult);
    emit!(crate::studio::types::SyncResult);
    emit!(crate::studio::types::BackupRequest);
    emit!(crate::studio::types::RestoreRequest);
    emit!(crate::studio::types::GenerateRequest);
    emit!(crate::studio::types::MaskRequest);
    emit!(crate::studio::types::Job);
    emit!(crate::studio::types::Dashboard);
    emit!(crate::studio::types::ModelAttr);
    emit!(crate::studio::types::ModelEntity);
    emit!(crate::studio::types::ModelRel);
    emit!(crate::studio::types::DataModel);
    emit!(crate::studio::types::Favorite);
    emit!(crate::studio::types::AiSettingsRequest);
    emit!(crate::studio::types::AiSettingsPublic);
    emit!(crate::studio::types::AiAskRequest);
    emit!(crate::studio::types::DesignColumn);
    emit!(crate::studio::types::DesignRequest);
    emit!(crate::studio::types::MailSettings);
    emit!(crate::studio::types::MailSave);
    emit!(crate::studio::types::DebugReport);
    emit!(crate::studio::types::ForeignKeyRef);
    emit!(crate::catalogdiff::SyncStatement);
    emit!(crate::plan::PlanNode);
    emit!(crate::pldbg::DebugCell);
    emit!(crate::pldbg::DebugSnapshot);
    emit!(crate::operations::OperationSnapshot);
    emit!(crate::run_history::RunRecord);
    emit!(crate::capabilities::EngineCapabilities);
    let capabilities: Vec<_> = crate::capabilities::ENGINES
        .iter()
        .map(|engine| engine.capabilities())
        .collect();
    output.push_str("export const ENGINE_CAPABILITIES: readonly EngineCapabilities[] = ");
    output.push_str(&serde_json::to_string_pretty(&capabilities).unwrap());
    output.push_str(";\n");
    let commands: Vec<_> = include_str!("commands.rs")
        .split("#[tauri::command]")
        .skip(1)
        .map(|part| {
            part.split("fn ")
                .nth(1)
                .unwrap()
                .split('(')
                .next()
                .unwrap()
                .trim()
        })
        .collect();
    output.push_str("export const COMMAND_NAMES = ");
    output.push_str(&serde_json::to_string(&commands).unwrap());
    output.push_str(" as const;\nexport type CommandName = typeof COMMAND_NAMES[number];\n");
    let output = output.lines().map(str::trim_end).collect::<Vec<_>>().join("\n") + "\n";
    let target =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/generated/contracts.ts");
    if std::env::var_os("DATAHARBOR_UPDATE_CONTRACTS").is_some() {
        std::fs::create_dir_all(target.parent().unwrap()).unwrap();
        std::fs::write(&target, &output).unwrap();
    } else {
        assert_eq!(
            std::fs::read_to_string(&target)
                .unwrap_or_default()
                .replace("\r\n", "\n"),
            output,
            "Rust/TypeScript contracts changed: run npm run contracts:generate"
        );
    }
}
